import {lessons} from './data.js';
import {$,intro,read,save,toast} from './ui.js';
let completed=read('completed',[]);if(!Array.isArray(completed))completed=[];
const colors=['Black','Brown','Red','Orange','Yellow','Green','Blue','Violet','Gray','White'];
const hex=['#222822','#75452e','#bd4432','#ed9151','#dfcb5d','#59825b','#49718a','#865583','#92968a','#f5f5e8'];
function resistance(n){return n>=1e6?+(n/1e6).toPrecision(5)+' MΩ':n>=1000?+(n/1000).toPrecision(5)+' kΩ':+n.toPrecision(5)+' Ω'}
export function path(){
 $('#main').innerHTML=intro('05 / a little progress, every session','From curious<br><em>to capable.</em>','Build a circuit. Understand a fault. Repeat. This balanced path gives you a first foothold in both making and repair.')+`<div class="path-header"><span class="section-label" id="path-progress"></span><div class="progress-track"><i id="progress-fill"></i></div><span class="small-note" style="margin:0">Saved on this browser</span></div><section class="path-layout"><div>${lessons.map((l,i)=>`<article class="lesson ${completed.includes(l.id)?'done':''}" id="lesson-${l.id}"><span class="lesson-num">${completed.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${l.title}</h3><div class="meta">${l.time} suggested · go at your own pace</div><p>${l.task}</p><details><summary>The idea to take with you</summary><p>${l.know}</p></details><div class="lesson-actions"><a class="btn outline small" href="${l.route}">${l.id==='datasheet'?'Open reference tools below ↓':'Go to the activity ↗'}</a><label><input type="checkbox" data-lesson="${l.id}" ${completed.includes(l.id)?'checked':''}>I can explain this</label></div></div></article>`).join('')}</div><aside class="path-aside"><section class="white-panel"><div class="eyebrow">A small, useful starter bench</div><h3>Buy for your next project.</h3><ul class="kit-list"><li>Temperature-controlled soldering station, stable stand, and an appropriate chisel tip</li><li>Electronics solder and flux, tip cleaner, fume extraction, and eye protection</li><li>Digital multimeter with fused current input, continuity, and diode modes</li><li>Flush cutters, tweezers, wire stripper, magnifier, and PCB holder</li><li>Breadboard, jumper wires, switched AA holder, and through-hole practice board</li><li>Resistors, small LEDs, ceramic and electrolytic capacitors, buttons, and header pins</li></ul><p class="small-note">An oscilloscope, hot-air station, and microscope can wait until a project needs them. Avoid large random assortments before you know the values and packages you use.</p></section><section class="white-panel"><div class="eyebrow">Useful habits beyond soldering</div><h3>Make your thinking visible.</h3><ul class="kit-list"><li>Sketch the schematic before wiring. Name your ground and supply nodes.</li><li>Write a prediction before measuring. Record expected and actual values.</li><li>Read the pinout and recommended operating conditions for each exact part.</li><li>Use a current-limited supply when ready, and check for shorts before power-on.</li><li>Learn to desolder on a practice board before attempting a valuable repair.</li><li>Photograph each repair step and change one thing at a time.</li></ul></section><section class="white-panel"><div class="eyebrow">Learn from the source</div><h3>Keep these within reach.</h3><a class="resource" href="https://learn.sparkfun.com/tutorials/how-to-solder-through-hole-soldering" target="_blank" rel="noreferrer">Through-hole soldering <span>↗</span><small>SparkFun · technique and demonstrations</small></a><a class="resource" href="https://learn.adafruit.com/multimeters/overview?view=all" target="_blank" rel="noreferrer">Using a multimeter <span>↗</span><small>Adafruit · voltage, resistance, continuity, current</small></a><a class="resource" href="https://learn.sparkfun.com/tutorials/how-to-use-a-breadboard/all" target="_blank" rel="noreferrer">How breadboards connect <span>↗</span><small>SparkFun · internal strips and divided rails</small></a><a class="resource" href="https://www.ti.com/product-category/power-management/mosfets/overview.html" target="_blank" rel="noreferrer">Understanding MOSFETs <span>↗</span><small>Texas Instruments · datasheet and application resources</small></a><p class="small-note">Use the manufacturer’s datasheet for the exact part on your bench. These references supplement the workshop’s simplified teaching models.</p></section></aside></section><div class="section-heading" id="reference-tools"><h2>A little decoding help.</h2><p>Markings are clues.<br>The datasheet is the authority.</p></div><div class="unit-tools"><section class="white-panel"><div class="eyebrow">Four-band resistors</div><h3>Turn colors into a value.</h3><div class="band-resistor" id="band-preview"></div><div class="band-row">${['First digit','Second digit','Multiplier','Tolerance'].map((n,i)=>`<label>${n}<select id="band-${i}" aria-label="${n}">${i<2?colors.map((c,j)=>i===0&&j===0?'':`<option value="${j}" ${j===3?'selected':''}>${c} · ${j}</option>`).join(''):i===2?[['-2','Silver ×0.01'],['-1','Gold ×0.1'],...colors.slice(0,8).map((c,j)=>[j,c+' ×10^'+j])].map(([v,n])=>`<option value="${v}" ${+v===1?'selected':''}>${n}</option>`).join(''):'<option value="5">Gold · ±5%</option><option value="10">Silver · ±10%</option><option value="1">Brown · ±1%</option><option value="2">Red · ±2%</option>'}</select></label>`).join('')}</div><div class="code-answer" id="band-result" aria-live="polite"></div><p class="small-note" id="band-range"></p><p class="small-note">Two digits × multiplier, then tolerance. Five-band precision codes use three digits instead.</p></section><section class="white-panel"><div class="eyebrow">Common chip markings</div><h3>Decode an SMD resistor.</h3><label for="smd-code" class="small-note" style="display:block">Try 103, 1002, 4R7, or 000</label><input class="code-input" id="smd-code" value="103" maxlength="12" spellcheck="false" autocomplete="off"><div class="code-answer" id="smd-result" aria-live="polite"></div><p class="small-note" id="smd-explanation"></p><p class="small-note">This tool handles common 3/4-digit and R decimal codes. EIA-96 letter codes need a separate lookup; many very small resistors have no markings.</p></section></div><div class="section-heading"><h2>Concepts you’ll keep coming back to.</h2></div><div class="glossary-grid">${[
 ['Series & parallel','Series parts share the same current. Parallel branches share the same voltage. Series resistances add; for parallel resistors, 1/Req = 1/R1 + 1/R2 + … .'],
 ['Kirchhoff’s laws','At a node, total current entering equals total current leaving. Around a closed loop, voltage rises and drops sum to zero. Current is not consumed; energy is transferred.'],
 ['Ground & earth','Ground is the reference node chosen as 0 V. Protective earth is a physical safety connection. They are not automatically the same, and two circuits can have different references.'],
 ['Decoupling','A capacitor close to IC power pins supplies short bursts of local current and reduces supply disturbances. Its placement and return path matter as well as capacitance.'],
 ['Tolerance & ratings','A 1 kΩ ±5% resistor may measure between 950 and 1050 Ω. Voltage, current, power, and temperature ratings are separate limits. Absolute maximums are not normal operating targets.'],
 ['Breadboard connections','Groups of holes are linked by metal strips. Opposite sides of the center gap are separate. Long power rails may be split halfway; confirm continuity before using them.'],
 ['Open circuit vs short','An open breaks an intended current path. A short creates an unintended low-resistance path. Zero volts across a part can have many causes: trace the surrounding circuit before concluding.'],
 ['Schematic vs PCB','A schematic groups parts by electrical function. A PCB places and routes them physically. The same node may span many traces, vias, or a copper plane, even when components are far apart.'],
 ['Reading tiny units','1 kΩ = 1,000 Ω; 1 MΩ = 1,000,000 Ω. 1 µF = 1,000 nF = 1,000,000 pF. The letter case matters: m means milli, M means mega.']
 ].map(([title,desc])=>`<details><summary>${title}</summary><p>${desc}</p></details>`).join('')}</div><p class="source-note">Your completion marks and explored components stay in this browser’s local storage. They are not synced between devices.</p>`;
 $('#main').onchange=e=>{if(e.target.dataset.lesson){const id=e.target.dataset.lesson;if(e.target.checked){if(!completed.includes(id))completed.push(id)}else completed=completed.filter(x=>x!==id);save('completed',completed);const row=$('#lesson-'+id);row.classList.toggle('done',e.target.checked);row.querySelector('.lesson-num').textContent=e.target.checked?'✓':String(lessons.findIndex(x=>x.id===id)+1).padStart(2,'0');progress();if(e.target.checked)toast('One more connection made.')}if(e.target.id.startsWith('band-'))decodeBands()};$('#smd-code').oninput=decodeSmd;
 const finalLink=$('#lesson-datasheet a');finalLink.onclick=e=>{e.preventDefault();$('#reference-tools').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};progress();decodeBands();decodeSmd();
}
function progress(){$('#path-progress').textContent=`${completed.length} / ${lessons.length} steps explored`;$('#progress-fill').style.width=completed.length/lessons.length*100+'%'}
function decodeBands(){const vals=[0,1,2,3].map(i=>+$('#band-'+i).value);const n=(vals[0]*10+vals[1])*10**vals[2];$('#band-result').textContent=resistance(n)+' ±'+vals[3]+'%';$('#band-range').textContent='Expected range: '+resistance(n*(1-vals[3]/100))+' – '+resistance(n*(1+vals[3]/100));$('#band-preview').innerHTML=[hex[vals[0]],hex[vals[1]],vals[2]===-2?'#acb6ad':vals[2]===-1?'#a68a42':hex[vals[2]],({5:'#a68a42',10:'#acb6ad',1:hex[1],2:hex[2]})[vals[3]]].map(c=>`<i style="background:${c}"></i>`).join('')}
function decodeSmd(){const code=$('#smd-code').value.trim().toUpperCase();let n,explain;if(/^\d{3,4}$/.test(code)){n=+code.slice(0,-1)*10**+code.at(-1);explain=`The first ${code.length-1} digits are the significant value; the last digit is the power-of-ten multiplier.`}else if(/^(?:\d+R\d*|R\d+)$/.test(code)){n=+code.replace('R','.');explain='R marks the decimal point in a value expressed in ohms.'}else{explain='Enter a 3- or 4-digit code, or an R decimal value. Other marking systems are not decoded here.'}$('#smd-result').textContent=n===undefined?'Check the code':resistance(n);$('#smd-explanation').textContent=explain}
